      "text": "French and Indian War: Robert Rogers and his Rangers surprise French held Fort Sainte Thérèse on the Richelieu River near Lake Champlain. The fort is raided and burned.",
      "id": "wiki-en-d1a281674e385fb9",
      "sourceUrl": "https://en.wikipedia.org/wiki/June_16?oldid=1370675600",
